ManagedAuthTimelineEvent {"description": "A single event in an auth connection's history \u2014 a login attempt, an automatic re-auth attempt, or a health check.", "properties": {"browser_session_id": {"description": "Browser session that produced the event, if one was created.", "type": "string"}, "completed_at": {"description": "When the login/reauth attempt first reached a terminal status. Stable across retries and subsequent cleanup writes. Absent for in-progress attempts, health checks, and historical attempts without a recorded completion time.", "format": "date-time", "type": "string"}, "error_code": {"description": "Machine-readable error code. Present when a login/reauth event failed.", "type": "string"}, "error_message": {"description": "Human-readable error message. Present when a login/reauth event failed.", "type": "string"}, "id": {"description": "Identifier of the underlying login/reauth session or health check.", "type": "string"}, "previous_status": {"description": "The session state observed before this event. Present for health_check events that recorded a prior state.", "enum": ["AUTHENTICATED", "NEEDS_AUTH"], "type": "string"}, "replay_id": {"description": "Replay recording ID for the event's browser session, if session recording was enabled.", "type": "string"}, "status": {"description": "Outcome of the event. For login/reauth events this is the flow status\n(IN_PROGRESS, SUCCESS, EXPIRED, CANCELED, FAILED). For health_check events\nit is the observed session state (AUTHENTICATED, NEEDS_AUTH).\n", "enum": ["IN_PROGRESS", "SUCCESS", "EXPIRED", "CANCELED", "FAILED", "AUTHENTICATED", "NEEDS_AUTH"], "type": "string"}, "step": {"description": "The step the flow reached. Present for login/reauth events.", "enum": ["INITIALIZED", "DISCOVERING", "AWAITING_INPUT", "AWAITING_EXTERNAL_ACTION", "AWAITING_HUMAN_INTERVENTION", "SUBMITTING", "COMPLETED", "EXPIRED"], "type": "string"}, "telemetry_captured": {"description": "Whether browser telemetry capture started for this event's browser session.", "type": "boolean"}, "timestamp": {"description": "When the event occurred.", "format": "date-time", "type": "string"}, "type": {"description": "The kind of event. \"login\" and \"reauth\" are authentication attempts; \"health_check\" is a periodic session-validity check.", "enum": ["login", "reauth", "health_check"], "type": "string"}, "updated_at": {"description": "When the event was last updated. Present for login/reauth events.", "format": "date-time", "type": "string"}, "website_error": {"description": "Visible error message from the website (e.g., 'Incorrect password'). Present when the website displayed an error during the attempt.", "type": "string"}}, "required": ["type", "id", "timestamp", "status"], "type": "object"}
