def causal_threads(cfg, run):
    """Only exact run roots and their durable private handoffs are evidence."""
    threads = {(root['channel'], root['ts']) for root in run['roots']}
    path = cfg.lab_home / '.clanker-vault/requests.sqlite'
    if not path.exists():
        return threads
    owners = {cfg.testers[name]['user'] for name in run['testers']}
    try:
        with readonly(path) as db:
            rows = db.execute('SELECT team,owner,original_source,source FROM transfers WHERE team=?', (cfg.team_id,)).fetchall()
        for _ in range(8):
            before = set(threads)
            for row in rows:
                if row['owner'] not in owners or not row['source']:
                    continue
                original, destination = json.loads(row['original_source']), json.loads(row['source'])
                if (original.get('chat_id'), original.get('thread_id')) in threads:
                    channel, thread = destination.get('chat_id'), destination.get('thread_id')
                    if isinstance(channel, str) and isinstance(thread, str) and re.fullmatch(r'\d+\.\d+', thread):
                        threads.add((channel, thread))
            if threads == before:
                break
    except (sqlite3.Error, ValueError, TypeError):
        raise QAError('Private handoff correlation could not be verified; unrelated timed activity was excluded.') from None
    return threads


